SET @s=27; SET @r=(SELECT id FROM knowledge_nodes WHERE subject_id=@s AND level=1 LIMIT 1);

-- == 第1章 测量基础知识 ==
SET @ch=(SELECT id FROM knowledge_nodes WHERE parent_id=@r AND name='测量基础知识');

SET @u=(SELECT id FROM knowledge_nodes WHERE parent_id=@ch AND name='测量学概述');
UPDATE knowledge_nodes SET content='# 测量学的分类与任务\n\n【一句话定义】测量学分为大地测量学(研究地球形状大小/建立国家控制网)、地形测量学(测绘地形图)、摄影测量学(航空/卫星影像测图)、工程测量学(工程建设各阶段的测量工作)、地图制图学(地图编制与出版)。建筑工程中主要用到工程测量和地形测量。\n\n【具体例子】修一条高速公路:勘测设计阶段用地形测量测绘1:2000带状地形图→施工阶段用工程测量放样路线中线/桥梁墩台→竣工后测量验收。\n\n【考点提示·笔试】选择/判断:测量学五大分支的名称配对。建筑工程常用的是工程测量学和地形测量学。' WHERE subject_id=@s AND level=4 AND name LIKE '%分类与任务%';
UPDATE knowledge_nodes SET content='# 测量工作的基本原则\n\n【一句话定义】"从整体到局部,先控制后碎部,前一步未检核不进行下一步"。含义:先建立高精度的控制网(平面控制+高程控制)→再以控制点为依据进行碎部测量(测绘地物地貌)→每一步成果必须检核合格后才能进行下一步,防止误差累积。\n\n【具体例子】测绘一个小区的地形图:先在小区外围布设4个GPS控制点(控制测量)→在每个控制点上设站测量周边房屋/道路/树木的位置(碎部测量)→测完后检查邻近测站重叠区域是否吻合(检核)。\n\n【考点提示·笔试】必考简答:测量工作的基本原则及含义。口诀记忆:"整体→局部,控制→碎部,步步检核"。' WHERE subject_id=@s AND level=4 AND name LIKE '%基本原则%';

SET @u=(SELECT id FROM knowledge_nodes WHERE parent_id=@ch AND name='地面点位的确定');
UPDATE knowledge_nodes SET content='# 大地水准面与高程系统\n\n【一句话定义】大地水准面:与平均海水面相吻合的静止封闭曲面(测量工作的基准面)。绝对高程(海拔):地面点沿铅垂线到大地水准面的垂直距离(如珠峰8848.86m)。相对高程(假定高程):地面点到任意假定水准面的垂直距离(工地上常用假定±0.000)。高差:两点高程之差(hAB=HB-HA)。\n\n【具体例子】建筑施工图上标注的±0.000是底层室内地坪的相对标高(假定高程)。国家测绘的GPS控制点标注的是1985国家高程基准的绝对高程。\n\n【考点提示·笔试】辨析:绝对高程vs相对高程的基准面不同。选择:我国高程基准是1985国家高程基准。' WHERE subject_id=@s AND level=4 AND name LIKE '%大地水准面%高程%';
UPDATE knowledge_nodes SET content='# 平面直角坐标系与坐标增量\n\n【一句话定义】测量平面直角坐标系:X轴指向正北方向(纵轴)/Y轴指向正东方向(横轴)/象限按顺时针编号(与数学坐标系相反)。坐标增量:两点间的X坐标差(ΔXAB=XB-XA=平距×cos方位角)和Y坐标差(ΔYAB=YB-YA=平距×sin方位角)。\n\n【具体例子】已知A点坐标(1000,2000),AB距离100m,方位角30°→ΔX=100×cos30°=86.6m→XB=1086.6;ΔY=100×sin30°=50m→YB=2050。\n\n【考点提示·笔试】必考计算:给起点坐标/距离/方位角→求终点坐标。注意:测量坐标系与数学坐标系的X/Y轴互换且象限顺序不同。' WHERE subject_id=@s AND level=4 AND name LIKE '%平面直角坐标%坐标增量%';

SET @u=(SELECT id FROM knowledge_nodes WHERE parent_id=@ch AND name='测量误差基础');
UPDATE knowledge_nodes SET content='# 系统误差与偶然误差的区别\n\n【一句话定义】系统误差:符号和大小固定或有规律变化(如钢尺比标准尺长或短/水准仪视准轴不平行于水准管轴)、可通过校正仪器或加改正数消除或削弱。偶然误差:符号和大小随机变化无规律(如读数估读误差/瞄准偏差)、不可完全消除但可通过多次观测取平均值减小、具有统计规律(正态分布/抵偿性)。粗差(错误):观测者操作失误(如读错数/记错/目标瞄错)→应通过检核发现并重测,不允许存在于成果中。\n\n【考点提示·笔试】简答高频:系统误差与偶然误差的区别(符号规律/可消除性/处理方法)。' WHERE subject_id=@s AND level=4 AND name LIKE '%系统误差%偶然误差%';
UPDATE knowledge_nodes SET content='# 中误差与容许误差的计算\n\n【一句话定义】中误差(均方根误差):m=±√([ΔΔ]/n)(Δ为真误差/n为观测次数)反映观测精度。相对误差:中误差的绝对值与观测值之比(一般化为分子为1的分数如1/2000)用于距离测量精度评价。容许误差(极限误差):Δ容=±2m~±3m(置信概率95.5%~99.7%)用于检核观测成果是否超限。\n\n【具体例子】丈量一段距离往返测:往测120.45m/返测120.49m→差值0.04m/平均值120.47m→相对误差=0.04/120.47≈1/3000<容许1/2000→合格。\n\n【考点提示·笔试】必考计算:给一组观测值和真值→计算中误差;给往返测距离→求相对误差并判断是否超限。' WHERE subject_id=@s AND level=4 AND name LIKE '%中误差%容许误差%';

-- == 第2章 水准测量 ==
SET @ch=(SELECT id FROM knowledge_nodes WHERE parent_id=@r AND name='水准测量');

SET @u=(SELECT id FROM knowledge_nodes WHERE parent_id=@ch AND name='水准仪构造与使用');
UPDATE knowledge_nodes SET content='# DS3水准仪的构造\n\n【一句话定义】DS3微倾式水准仪由三部分组成:望远镜(物镜/目镜/十字丝分划板/调焦透镜→提供水平视线并瞄准标尺)、水准器(圆水准器(粗平→气泡居中)/管水准器(精平→气泡居中/灵敏度20′/2mm))、基座(连接三脚架/三个脚螺旋整平仪器)。DS3中"D"=大地测量/"S"=水准仪/"3"=每千米往返测高差中数中误差≤±3mm。\n\n【考点提示·笔试】选择:DS3各字母含义/各部件的功能。' WHERE subject_id=@s AND level=4 AND name LIKE '%DS3%水准仪%构造%';
UPDATE knowledge_nodes SET content='# 水准尺的读数方法\n\n【一句话定义】水准尺(塔尺/双面尺):塔尺可伸缩(3m或5m)/双面尺一面黑白(黑面/主尺)一面红白(红面/辅尺/常数差4.687m或4.787m)。读数方法:望远镜瞄准水准尺→调节物镜对光和目镜对光消除视差→用十字丝横丝(中丝)读取水准尺上数值→精确到mm(估读最后一位)。如中丝对准1.5m~1.6m之间约0.435m→读数为1.435m。\n\n【考点提示·笔试】实操题转换:给出水准尺示意图→写出正确读数。注意消除视差(读前必须检查/眼睛上下移动时读数不应变化)。' WHERE subject_id=@s AND level=4 AND name LIKE '%水准尺%读数%';

SET @u=(SELECT id FROM knowledge_nodes WHERE parent_id=@ch AND name='水准测量方法');
UPDATE knowledge_nodes SET content='# 水准测量原理(高差=后视-前视)\n\n【一句话定义】水准测量是利用水准仪提供的水平视线,配合水准尺测定两点间高差的方法。在A、B两点立水准尺,中间安置水准仪→分别读取A尺(后视读数a)和B尺(前视读数b)→高差hAB=a-b。hAB>0表示B点高于A点,hAB<0表示B点低于A点。HB=HA+hAB(已知HA可求HB)。\n\n【具体例子】已知A点高程HA=100.000m,后视读数a=1.528m,前视读数b=0.734m→hAB=1.528-0.734=+0.794m→HB=100.000+0.794=100.794m。\n\n【考点提示·笔试】必考计算:给后视/前视读数求高差和待定点高程。口决:高差=后-前;高程递推:HB=HA+hAB。' WHERE subject_id=@s AND level=4 AND name LIKE '%水准测量原理%高差%后视%前视%';
UPDATE knowledge_nodes SET content='# 两次仪器高法的操作步骤\n\n【一句话定义】两次仪器高法(双仪高法):在同一测站上,改变仪器高度(升高或降低>10cm)进行两次观测,分别计算高差→若两次高差之差≤±5mm(等外水准)则取平均值作为该站高差,否则重测。目的:检核观测是否正确,防止读数错误。\n\n【考点提示·笔试】简答:两次仪器高法的目的(检核读数)和限差要求(|h1-h2|≤±5mm)。' WHERE subject_id=@s AND level=4 AND name LIKE '%两次仪器高%';

SET @u=(SELECT id FROM knowledge_nodes WHERE parent_id=@ch AND name='水准路线与成果校核');
UPDATE knowledge_nodes SET content='# 闭合/附合/支水准路线的计算\n\n【一句话定义】闭合水准路线:从已知高程点出发→测若干待定点→回到原已知点(∑h理=0)。附合水准路线:从一个已知点→测若干待定点→另一个已知点(∑h理=HB-HA)。支水准路线:从已知点→待定点→无法检核→必须往返测。高差闭合差fh=实测高差之和-理论高差之和。若fh≤fh容(容许闭合差)→调整闭合差(按测站数或路线长成比例分配到各段)→计算各点高程。\n\n【具体例子】附合水准路线:A(HA=100.000)→1→2→B(HB=102.500),实测∑h=+2.480m→fh=2.480-2.500=-0.020m=-20mm。共4个测站→每站改正+5mm。\n\n【考点提示·笔试】必考计算:给观测数据和已知高程→求闭合差→判断是否合格→分配→计算各点高程。' WHERE subject_id=@s AND level=4 AND name LIKE '%闭合%附合%支水准%';
UPDATE knowledge_nodes SET content='# 水准测量成果的容许闭合差\n\n【一句话定义】等外水准测量容许闭合差:平地fh容=±40√L mm(L为路线总长/km)、山地fh容=±12√n mm(n为测站总数)。四等水准:平地fh容=±20√L mm、山地fh容=±6√n mm。若|fh|≤fh容→成果合格,可分配闭合差;若|fh|>fh容→超限→重测。\n\n【考点提示·笔试】必考判断:给闭合差和容许值→判断是否合格。选择:容许闭合差公式的适用条件(平地用L/山地用n)。' WHERE subject_id=@s AND level=4 AND name LIKE '%容许闭合差%';

-- == 第3章 角度测量 ==
SET @ch=(SELECT id FROM knowledge_nodes WHERE parent_id=@r AND name='角度测量');

SET @u=(SELECT id FROM knowledge_nodes WHERE parent_id=@ch AND name='经纬仪构造与使用');
UPDATE knowledge_nodes SET content='# DJ6光学经纬仪的构造与读数\n\n【一句话定义】DJ6光学经纬仪由照准部(望远镜/竖盘/水准器→瞄准目标和测量竖直角)、水平度盘(0°~360°顺时针注记→测量水平角)、基座(连接三脚架/脚螺旋整平)三部分组成。DJ6中"D"=大地测量/"J"=经纬仪/"6"=一测回方向中误差≤±6′。\n\n【考点提示·笔试】选择:经纬仪各部件的名称和功能配对。DJ6含义。' WHERE subject_id=@s AND level=4 AND name LIKE '%DJ6%经纬仪%构造%';
UPDATE knowledge_nodes SET content='# 经纬仪的安置(对中/整平)\n\n【一句话定义】对中:使仪器竖轴中心对准测站点(垂球对中精度±3mm/光学对中器精度±1mm)。整平:使水平度盘处于水平位置(先粗平(升降脚架+圆水准器)→再精平(用脚螺旋+管水准器/水准管轴平行于两脚螺旋连线))。对中和整平交替进行→最终同时满足对中和整平要求。\n\n【考点提示·笔试】简答:经纬仪安置步骤和对中整平的要求。' WHERE subject_id=@s AND level=4 AND name LIKE '%对中%整平%';

SET @u=(SELECT id FROM knowledge_nodes WHERE parent_id=@ch AND name='水平角测量');
UPDATE knowledge_nodes SET content='# 测回法测量水平角的操作\n\n【一句话定义】测回法(适用于两方向间水平角测量):上半测回(盘左/正镜):瞄准左目标A→读数a左→顺时针旋转瞄准右目标B→读数b左→β左=b左-a左。下半测回(盘右/倒镜):倒转望远镜→瞄准B→读数b右→逆时针旋转瞄准A→读数a右→β右=b右-a右。若|β左-β右|≤±40′(DJ6)则取平均值β=(β左+β右)/2。\n\n【具体例子】上半测回:a左=0°03′30′,b左=85°26′42′→β左=85°23′12′。下半测回:b右=265°26′54′,a右=180°03′42′→β右=85°23′12′。Δ=0→合格→β=85°23′12′。\n\n【考点提示·笔试】必考简答+计算:测回法的操作步骤和记录计算方法。限差:上下半测回角值之差≤±40″。' WHERE subject_id=@s AND level=4 AND name LIKE '%测回法%水平角%';
UPDATE knowledge_nodes SET content='# 方向观测法(全圆测回法)\n\n【一句话定义】适用于三个及以上方向的水平角观测。观测顺序:盘左:选起始方向(归零方向)→顺时针依次瞄准A/B/C/D→再回到A(归零检核/半测回归零差≤±18″)。盘右:逆时针依次瞄准A/D/C/B→再回到A。各方向的2C(两倍视准轴误差)=盘左读数-(盘右读数±180°)→2C互差≤±36″。取盘左盘右平均值作为各方向最终值。\n\n【考点提示·笔试】简答:方向观测法的适用条件(≥3个方向)和观测顺序。' WHERE subject_id=@s AND level=4 AND name LIKE '%方向观测%全圆%';

SET @u=(SELECT id FROM knowledge_nodes WHERE parent_id=@ch AND name='竖直角测量');
UPDATE knowledge_nodes SET content='# 竖直角与指标差的计算\n\n【一句话定义】竖直角(竖盘读数换算而来):同一竖直面内视线方向与水平线之间的夹角(仰角为正/俯角为负)。竖盘指标差x:当视线水平时竖盘读数不为90°(盘左)或270°(盘右)的偏差。计算公式:盘左αL=90°-L;盘右αR=R-270°;指标差x=[(L+R)-360°]/2;最终α=(αL+αR)/2=(R-L-180°)/2。x绝对值反映仪器误差→需定期校正。\n\n【具体例子】L=81°30′,R=278°32′→αL=90°-81°30′=+8°30′;αR=278°32′-270°=+8°32′;x=(360°02′-360°)/2=+1′;α=+8°31′。\n\n【考点提示·笔试】必考计算:给L/R读数→求竖直角和指标差。' WHERE subject_id=@s AND level=4 AND name LIKE '%竖直角%指标差%';

-- == 第4章 距离测量与地形图 ==
SET @ch=(SELECT id FROM knowledge_nodes WHERE parent_id=@r AND name='距离测量与地形图');

SET @u=(SELECT id FROM knowledge_nodes WHERE parent_id=@ch AND name='距离测量方法');
UPDATE knowledge_nodes SET content='# 钢尺量距与视距测量的原理\n\n【一句话定义】钢尺量距:平坦地面直接丈量(往返测取平均值/相对误差≤1/2000~1/3000)。倾斜地面:分段丈量斜距+测竖直角→水平距D=斜距L×cosα。视距测量:利用经纬仪或水准仪望远镜中的视距丝(上下丝)配合标尺间接测距。视线水平时:D=Kl(K=100/乘常数;l=上丝-下丝=视距间隔);高差h=i-v(i仪器高/v中丝读数)。\n\n【具体例子】水准仪读取:上丝1.560m/下丝1.260m→l=0.300m→D=100×0.300=30.0m。经纬仪读取:上丝2.150/下丝1.850→l=0.300→斜距=30.0→竖直角α=5°→D=30.0×cos5°=29.9m。\n\n【考点提示·笔试】必考计算:给上下丝读数→求水平距离(注意视线是否水平)。' WHERE subject_id=@s AND level=4 AND name LIKE '%钢尺量距%视距测量%';
UPDATE knowledge_nodes SET content='# 距离测量成果的改正计算\n\n【一句话定义】钢尺量距三项改正:尺长改正(钢尺实际长度≠名义长度/ΔLd=测量距离×(实际尺长-名义尺长)/名义尺长)、温度改正(ΔLt=α×测量距离×(测量温度-检定温度)/α=1.2×10^-5/℃)、倾斜改正(将斜距归算为水平距离/ΔLh=-h²/(2D))。精密量距时三项改正均需计算。\n\n【具体例子】30m钢尺检定为29.995m→每量30m需改正-5mm。当量得150m→尺长改正=-25mm;温度改正:检定时20℃/实测35℃→ΔLt=1.2×10^-5×150×(35-20)=+27mm→总改正=+2mm。\n\n【考点提示·笔试】计算:给出检定数据和测量数据→计算三项改正→求实际距离。' WHERE subject_id=@s AND level=4 AND name LIKE '%距离测量%改正%';

SET @u=(SELECT id FROM knowledge_nodes WHERE parent_id=@ch AND name='全站仪使用');
UPDATE knowledge_nodes SET content='# 全站仪的基本功能与测量模式\n\n【一句话定义】全站仪(全站型电子速测仪)集电子经纬仪(测角)+光电测距仪(测距)+微处理器(数据采集计算存储)于一体。基本测量模式:角度测量(水平角/竖直角)、距离测量(斜距/平距/高差)、坐标测量(输入测站坐标和后视方位角→直接测定目标点三维坐标(X/Y/H))、放样测量(输入设计坐标→仪器指引放样点位置)。\n\n【考点提示·笔试】选择:全站仪的组成部分和主要功能。辨析:全站仪≠经纬仪(多了测距和数据处理功能)。' WHERE subject_id=@s AND level=4 AND name LIKE '%全站仪%基本功能%测量模式%';
UPDATE knowledge_nodes SET content='# 全站仪坐标测量与放样\n\n【一句话定义】坐标测量原理:已知测站点坐标(X0/Y0/H0)和后视方位角→全站仪自动计算测站点至目标点的方位角和水平距离→根据极坐标法实时计算目标点坐标并显示。放样(施工放样):输入设计点位坐标→仪器计算放样数据(方位角和距离)→旋转照准部至计算方位角→指示棱镜前后移动至计算距离→标定点位。\n\n【考点提示·笔试】简答:全站仪坐标测量的基本原理(极坐标法)。放样与测量的区别(已知→未知 vs 已知设计→实地标定)。' WHERE subject_id=@s AND level=4 AND name LIKE '%坐标测量%放样%';

SET @u=(SELECT id FROM knowledge_nodes WHERE parent_id=@ch AND name='地形图基本知识');
UPDATE knowledge_nodes SET content='# 地形图比例尺与符号\n\n【一句话定义】比例尺:图上距离与实地水平距离之比(1:M=图上d/实地D)。大比例尺(1:500~1:5000→建筑施工/城市规划)、中比例尺(1:1万~1:10万→工程勘察)、小比例尺(1:25万~1:100万→区域规划)。比例尺精度:图上0.1mm对应的实地距离(如1:500→0.05m=5cm)。地形图符号:比例符号(房屋/湖泊)、非比例符号(控制点/路灯→不按比例)、注记符号(地名/高程/说明)。\n\n【考点提示·笔试】选择:大/中/小比例尺的划分标准。比例尺精度概念和计算。' WHERE subject_id=@s AND level=4 AND name LIKE '%比例尺%符号%';
UPDATE knowledge_nodes SET content='# 等高线的概念与判读\n\n【一句话定义】等高线:地面上高程相等的相邻点连成的闭合曲线。基本特性:同一条等高线上各点高程相等/闭合(在图幅内或在图外)/不相交(悬崖除外)/密陡疏缓(等高线间距小=坡度大)/与山脊线(分水线)和山谷线(集水线)正交。等高距(相邻两等高线高差):大比例尺地形图1m~5m。典型地貌判读:山顶(闭合等高线内圈高)/鞍部(两组闭合等高线之间)/悬崖(等高线相交)。\n\n【考点提示·笔试】必考简答:等高线的5条基本特性。识图:给出等高线图→判断山顶/山脊/山谷/鞍部/陡崖。' WHERE subject_id=@s AND level=4 AND name LIKE '%等高线%';

SELECT 'v110: 工程测量 content注入完成' AS result;
